import CountryList from "@/JsonFiles/CountryList.json";
import { aseet_suppliers } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    supplierAddition: Boolean
  },
  components: {
    CountryList
  },
  data() {
    return {
      loading: false,
      supplierName: "",
      supplieraddress: "",
      contactName: "",
      supplieremailID: "",
      countryList: "",
      contactNumber: "",
      countryitems: [],
      rules: {
        required: value => !!value || "Required.",
        email: value => {
          if (value === "" || value === null) {
            return true;
          }
          const pattern = /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
          return pattern.test(value) || "Invalid Email";
        },
        phoneNumber: value => {
          return value && /^[0-9]{8,13}$/.test(value) || "Length must be between 8 and 13 digits";
        }
      }
    };
  },
  watch: {
    supplierAddition: {
      async handler() {
        if (this.supplierAddition == true) {
          this.countryList = "";
          this.contactNumber = "";
          this.supplieremailID = "";
          await this.fetch_details();
        }
      },
      immediate: true
    }
  },
  // watch: {
  //   supplierAddition: {
  //     async handler() {
  //       this.countryList = "";
  //       this.contactNumber = "";
  //       this.supplieremailID = "";
